#include "rtos_web.hpp"
#include <assert.h>
#include <string.h>
using namespace rtos::web;
static uint8_t payload[]={'o','k'};static Asset assets[]={{"/","text/plain",{payload,2}}};
struct Output{char data[2048]{};size_t used{};bool blocked{};};
int write(void* p,const uint8_t* data,size_t n){auto& out=*static_cast<Output*>(p);if(out.blocked)return 0;if(n>7)n=7;assert(out.used+n<sizeof(out.data));for(size_t i=0;i<n;++i)out.data[out.used++]=char(data[i]);return int(n);}
unsigned request(const char* text,bool head=false){Session s;assert(s.initialize(assets,1,0,100)==Result::ok);for(size_t i=0;i<strlen(text);++i){size_t n;auto result=s.feed({reinterpret_cast<const uint8_t*>(text+i),1},n);assert(n==1);(void)result;}Output out;out.blocked=true;assert(s.pump(write,&out)==Result::busy);out.blocked=false;for(unsigned i=0;i<100&&s.state()!=State::done;++i)s.pump(write,&out,13);assert(s.state()==State::done);assert(strstr(out.data,"Connection: close"));if(head)assert(out.used>=4&&out.data[out.used-4]=='\r'&&out.data[out.used-1]=='\n');return s.status();}
int main(){assert(request("GET / HTTP/1.0\r\nX-Test: a\rb\r\n\r\n")==400);assert(request("GET / HTTP/1.0\r\nX-Test: a\nb\r\n\r\n")==400);assert(request("GET / HTTP/1.0\r\n\r\n")==200);assert(request("HEAD / HTTP/1.1\r\nHost: board\r\n\r\n",true)==200);assert(request("GET /missing HTTP/1.0\r\n\r\n")==404);assert(request("GET / HTTP/1.1\r\n\r\n")==400);assert(request("GET / HTTP/1.1\r\nHost: a\r\nHost: b\r\n\r\n")==400);assert(request("GET / HTTP/1.0\r\nContent-Length: 1\r\n\r\n")==400);assert(request("GET / HTTP/1.0\r\nTransfer-Encoding: chunked\r\n\r\n")==400);assert(request("GET /../x HTTP/1.0\r\n\r\n")==400);assert(request("POST / HTTP/1.0\r\n\r\n")==405);assert(request("GET / HTTP/9.0\r\n\r\n")==505);assert(request("GET /?x=y HTTP/1.0\r\n\r\n")==200);Session s;assert(s.initialize(assets,1,5,10)==Result::ok&&s.expire(15)==Result::timeout);Asset duplicate[2]={assets[0],assets[0]};assert(s.initialize(duplicate,2,0,10)==Result::invalid);uint8_t out[128];JsonWriter json({out,sizeof(out)});json.text("{\"name\":");uint8_t name[]={'"','\n'};json.quoted({name,2});json.text(",\"cycles\":");json.unsigned_number(UINT64_MAX);json.text("}");assert(json.good()&&json.finish().size>30);JsonWriter tiny({out,1});tiny.text("long");assert(!tiny.good()&&tiny.finish().size==0);}
